var n=`0283-pljeskavica`;var t=`world-0283`;var r=`RS`;var o=`southern-europe`;var l=4;var a=65;var s={en:`Pljeskavica`,ua:`Плєскавіца`};var d={en:`A traditional Serbia dish made with ground beef, ground pork, yellow onion, garlic. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Сербія. Основні інгредієнти: яловичий фарш, свинячий фарш, жовта цибуля, часник. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-beef`,480,`g`],[`ground-pork`,270,`g`],[`yellow-onion`,130,`g`],[`garlic`,3,`clove`],[`sweet-paprika`,4,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 35 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 35 хвилин.`,t:[`rapid-chilling`],m:35,i:[]},{en:`Grill over medium-high heat for about 15 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 15 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:15,i:[[`sunflower-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`red-bell-pepper`,180,`g`],[`pita-bread`,300,`g`]]}];var u={slug:n,id:t,country:`RS`,region:o,servings:4,minutes:65,title:s,text:d,steps:g};export{r as country,u as default,t as id,a as minutes,o as region,l as servings,n as slug,g as steps,d as text,s as title};